// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address _vader,
        address _usdv,
        address _vault,
        address grantRecipient,
        uint256 grantAmount,
        address proposer1,
        address proposer2,
        uint256 oldProposalID,
        uint256 newProposalID
    ) public {
        // Assume unique addresses to avoid generic checks
        vm.assume(_vader != address(0) && _usdv != address(0) && _vault != address(0));
        vm.assume(grantRecipient != address(0));
        vm.assume(proposer1 != address(0) && proposer2 != address(0));
        vm.assume(proposer1 != proposer2);

        // Initialize the contract
        c.init(_vader, _usdv, _vault);

        // Get initial proposalCount
        uint256 initialCount = c.proposalCount();

        // Create two grant proposals to have something to cancel
        vm.prank(proposer1);
        c.newGrantProposal(grantRecipient, grantAmount);

        vm.prank(proposer2);
        c.newGrantProposal(grantRecipient, grantAmount);

        // Get current proposal count
        uint256 countAfterProposals = c.proposalCount();

        // Bound oldProposalID and newProposalID to valid range
        vm.assume(oldProposalID >= 1 && oldProposalID <= countAfterProposals);
        vm.assume(newProposalID >= 1 && newProposalID <= countAfterProposals);
        vm.assume(oldProposalID != newProposalID);

        // Try cancelling (may revert for various reasons, that's fine)
        // We're interested in the state after successful cancellation
        try c.cancelProposal(oldProposalID, newProposalID) {
            // If it succeeded, check that proposalCount didn't increase by 2
            uint256 finalCount = c.proposalCount();
            assertTrue(finalCount - initialCount != 2, "proposalCount should not be exactly 2 more than initial");
        } catch {
            // If revert, we just ensure it didn't incorrectly modify proposalCount to be exactly 2 more
            uint256 finalCount = c.proposalCount();
            assertTrue(finalCount - initialCount != 2, "proposalCount should not be exactly 2 more than initial");
        }
    }
}

