pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 initialCount;

    function setUp() public { 
        c = new C(); 
        initialCount = c.proposalCount();
    }

    function testFuzz_property(
        address recipient,
        address voter,
        uint256 amount,
        uint256 oldProposalID,
        uint256 newProposalID
    ) public {
        vm.assume(recipient != address(0));
        vm.assume(voter != address(0));
        vm.assume(recipient != voter);
        vm.assume(amount < 1e30);
        vm.assume(oldProposalID != newProposalID);
        vm.assume(oldProposalID >= 1 && oldProposalID <= 10);
        vm.assume(newProposalID >= 1 && newProposalID <= 10);

        // Create proposals to have valid IDs
        vm.startPrank(voter);
        c.newGrantProposal(recipient, amount);
        vm.stopPrank();

        // Need another proposal with different ID
        vm.startPrank(address(0x1234));
        c.newGrantProposal(recipient, amount);
        vm.stopPrank();

        // Ensure we have the right proposal IDs for cancelProposal
        uint256 currentCount = c.proposalCount();
        vm.assume(oldProposalID <= currentCount && newProposalID <= currentCount);

        // Try to make oldProposalID finalising (required for cancel)
        // We'll just attempt cancel and catch revert
        try c.cancelProposal(oldProposalID, newProposalID) {
            // If it succeeds, check the rule
            uint256 countAfter = c.proposalCount();
            assertTrue(countAfter != initialCount + 2, "proposalCount should not increase by exactly 2 after cancelProposal");
        } catch {
            // Revert is fine, no state change to check
            assertTrue(true);
        }
    }
}

