pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient, uint256 amount, uint256 oldPropId, uint256 newPropId) public {
        // Restrict inputs to avoid excessive rejection
        vm.assume(oldPropId > 0 && oldPropId <= 100);
        vm.assume(newPropId > 0 && newPropId <= 100);
        vm.assume(oldPropId != newPropId);

        // Record initial proposal count
        uint256 initialCount = c.proposalCount();

        // We need both proposals to exist. Create them via newGrantProposal calls.
        // The bug is in newGrantProposal, but we need cancelProposal to observe the difference.
        // Since we can't know exact IDs, we'll create proposals until we have at least max(oldPropId, newPropId) proposals.
        // But simpler: just use the IDs that would be assigned after creating proposals.

        // Create two proposals with known IDs (1 and 2)
        c.newGrantProposal(recipient, amount); // proposal 1
        c.newGrantProposal(recipient, amount); // proposal 2

        // At this point proposalCount should be 2. For M, it will be 4 due to the bug.
        // To trigger cancelProposal, we need old proposal to be finalising.
        // We can achieve this by voting and reaching majority/quorum.
        // But since we don't have a vault mocked, we rely on the fact that newGrantProposal doesn't require votes.
        // Actually, cancelProposal requires mapPID_finalising[oldProposalID] == true.
        // That requires finalise to have been started, which happens through voting.
        // Since we can't easily mock, we'll assume the test is about the state difference after the call.

        // Record count after creating proposals
        uint256 afterCreate = c.proposalCount();

        // Now call cancelProposal with the first two proposals (IDs 1 and 2)
        // But cancelProposal will revert if oldProposal is not finalising.
        // Since we can't easily make it finalising without mocking, we wrap in try/catch.

        // Actually, we can use vm.assume to avoid reverts, but cancelProposal will always revert because
        // the old proposal isn't finalising. So we just check that the call reverts or not.

        // Instead, we test the invariant that proposalCount never increments by more than 1 per newGrantProposal call.
        // The invariant: proposalCount - initialCount <= number of newGrantProposal calls * 1 (for reference)
        // For bug, it would be > when number of calls is 1 and bug increments by 2.

        // We already made 2 calls, so:
        uint256 delta = afterCreate - initialCount;
        assertTrue(delta == 2, "proposalCount should increase by exactly 1 per call");
    }
}

