pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        address addr1,
        address addr2,
        uint256 amount
    ) public {
        // Bound amount to avoid overflow issues in other functions
        vm.assume(amount > 0 && amount <= 1e30);

        // Ensure addr1 and addr2 are different
        vm.assume(addr1 != addr2);
        vm.assume(addr1 != address(0));
        vm.assume(addr2 != address(0));

        // Create two proposals of the same type via newGrantProposal (which uses proposalCount += 1)
        c.newGrantProposal(addr1, amount);
        uint256 firstId = c.proposalCount();

        c.newGrantProposal(addr2, amount);
        uint256 secondId = c.proposalCount();

        // Ensure second is different from first
        vm.assume(firstId != secondId);

        // Record proposalCount before cancel
        uint256 beforeCancel = c.proposalCount();

        // Attempt to cancelProposal: firstId must be finalising, secondId must have minority, etc.
        // Since we don't have finalising set, the call will revert. 
        // We catch the revert and check the invariant.
        try c.cancelProposal(firstId, secondId) {
            // If no revert, check that proposalCount did not increase
            uint256 afterCancel = c.proposalCount();
            assertTrue(afterCancel <= beforeCancel, "proposalCount should not increase after cancelProposal");
        } catch {
            // If revert, proposalCount should remain unchanged
            uint256 afterCancel = c.proposalCount();
            assertTrue(afterCancel == beforeCancel, "proposalCount should remain unchanged on revert");
        }
    }
}

