pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _vader, address _usdv, address _vault, uint256 oldProposalID, uint256 newProposalID) public {
        // Deploy and initialize
        vm.assume(_vader != address(0));
        vm.assume(_usdv != address(0));
        vm.assume(_vault != address(0));

        c.init(_vader, _usdv, _vault);

        // Record the initial VADER address
        address initialVader = c.VADER();

        // Prepare state to allow cancelProposal: need two proposals of same type with finalising on old and minority on new
        // First proposal (oldProposalID): use newAddressProposal to set some type, then call voteProposal to get majority and trigger _finalise
        // We'll create a proposal that will finalise
        c.newAddressProposal(_vader, "DAO");

        // Second proposal (newProposalID): create another proposal of same type
        c.newAddressProposal(_vader, "DAO");

        // Assume IDs are 1 and 2 (since we created two proposals)
        vm.assume(oldProposalID == 1 && newProposalID == 2);

        // Try to finalise the old proposal first to set mapPID_finalising[oldProposalID] = true
        // We need to vote on proposal 1 to trigger finalisation via hasMajority
        // But we need votes; simulate by calling voteProposal
        c.voteProposal(oldProposalID);

        // Now call cancelProposal
        c.cancelProposal(oldProposalID, newProposalID);

        // After cancelProposal, the VADER address should still be the initial value
        address finalVader = c.VADER();

        // Assert the general rule: VADER state variable remains unchanged
        assertTrue(finalVader == initialVader, "VADER address changed after cancelProposal");
    }
}

